export const trackingTemplate="    <section id=\"tracking-page\" class=\"page-view\" aria-label=\"가격 추적 페이지\">\n    <div class=\"page-heading\"><div><p class=\"eyebrow\">SAME PRODUCT. A DIFFERENT PRICE.</p><h1 id=\"tracking-title\" tabindex=\"-1\">같은 상품, 달라진 가격.</h1><p class=\"subtitle\">지난번보다 얼마나 달라졌을까요? 흩어진 구매 기록을 상품별로 이어보세요.</p></div></div>\n    <div id=\"sample-explainer\" class=\"sample-explainer\" hidden><div><strong>가상 메일로 살펴보는 가격 추적</strong><p>서로 다른 HTML 주문서, 전달 메일, 결제 영수증과 부분 취소 내역을 실제 가져오기와 같은 규칙으로 처리합니다.</p></div><div class=\"sample-cases\"><button class=\"button small\" data-sample-search=\"오트 밀크\">가격 변화 · 할인</button><button class=\"button small\" data-sample-search=\"커팅매트\">영수증 연결 · 부분 취소</button><button class=\"button small\" data-sample-search=\"데일리 코튼 패브릭\">잘린 상품명 · 수량</button><button class=\"button small\" data-sample-search=\"\">전체 샘플</button><button class=\"text-button\" id=\"return-records-tracking\" hidden>내 기록으로 돌아가기</button></div><p class=\"field-help\">모든 메일·상점·금액은 가상입니다. 샘플의 확인·연결 변경은 실제 기록에 저장되지 않습니다.</p></div>\n    <div id=\"tracking-notice\" class=\"notice\" role=\"status\" aria-live=\"polite\"></div>\n    <section class=\"metrics\" aria-label=\"구매 현황\">\n<div class=\"metric\"><span>주문/결제 횟수</span><strong id=\"metric-orders\">0<small>회</small></strong><p>주문·결제 식별 기준 · 중복 통합</p></div>\n<div class=\"metric\"><span>구매한 상품</span><strong id=\"metric-items\">0<small>개</small></strong><p>상품명 기준 · 옵션·용량·구성 구분</p></div>\n<div class=\"metric attention\"><span>검토 필요</span><strong id=\"metric-review\">0<small>건</small></strong><p>상품·가격 확인 · 정보 충돌</p></div></section>\n    <section class=\"records\" aria-label=\"가격 추적\">\n      <div class=\"records-heading\"><div><h2>상품별 가격 변화 <span id=\"record-count\">0</span></h2><p id=\"dataset-note\">가상 주문 자료로 기능을 체험할 수 있어요.</p></div><span class=\"session-label\" id=\"session-label\">SAMPLE SESSION</span></div>\n      <div class=\"table-toolbar\"><div class=\"tabs\" role=\"tablist\" aria-label=\"상태 필터\"><button role=\"tab\" aria-selected=\"true\" data-filter=\"all\">전체</button><button role=\"tab\" aria-selected=\"false\" data-filter=\"review\">검토 필요 <span id=\"review-count\">0</span></button><button role=\"tab\" aria-selected=\"false\" data-filter=\"repeat\">반복 구매</button></div><label class=\"search\"><span>⌕</span><input type=\"search\" id=\"search-input\" placeholder=\"상품명, 제조사, 판매자 검색\" aria-label=\"상품명, 제조사 또는 판매자 검색\"></label></div>\n      <div class=\"table-scroll\"><table class=\"product-table\"><caption class=\"sr-only\">상품별 최신 소비자가, 명시된 할인 내역과 직전 구매 대비 변화. 구매 이력을 펼쳐 상세 내역을 확인하세요.</caption><thead><tr><th>상품 / 식별 기준</th><th>최근 소비자가</th><th>할인가 / 할인율</th><th>직전 구매 대비</th><th>최근 구매일</th><th>구매 이력</th></tr></thead><tbody id=\"records-body\"></tbody></table></div>\n      <div class=\"empty\" id=\"empty\" hidden><span>⌕</span><h3>표시할 기록이 없어요</h3><p>검색 조건을 바꾸거나 주문 메일을 가져와주세요.</p></div>\n      <div class=\"table-footer\"><span id=\"visible-count\">0개 항목</span><span>소비자가 미표기 시 결제·주문가 사용 · 할인 근거가 있을 때만 별도 표시</span></div>\n    </section>\n\n  </section>\n";
